package com.mestryer.pixelsky.app.ui; import com.mestryer.pixelsky.core.model.Level; import com.mestryer.pixelsky.core.service.LevelCrudService; import javafx.geometry.Insets; import javafx.scene.Scene; import javafx.scene.control.*; import javafx.scene.layout.*; import javafx.stage.*; public class LevelCrudWindow {private final LevelCrudService s;public LevelCrudWindow(LevelCrudService s){this.s=s;}public void show(){Stage w=new Stage();w.setTitle("CRUD de Niveles");w.initModality(Modality.APPLICATION_MODAL);ListView<String> list=new ListView<>();refresh(list);TextField id=new TextField(),num=new TextField(),name=new TextField();id.setPromptText("ID");num.setPromptText("Número");name.setPromptText("Nombre");Button c=new Button("CREATE"),r=new Button("READ"),u=new Button("UPDATE"),d=new Button("DELETE"),all=new Button("READ ALL");c.setOnAction(e->{try{s.create(Level.builder().id(id.getText()).number(Integer.parseInt(num.getText())).name(name.getText()).description("Creado por CRUD").width(2400).height(900).build());refresh(list);}catch(Exception x){error(x.getMessage());}});r.setOnAction(e->{Level l=s.read(id.getText());if(l==null)error("No existe");else{num.setText(""+l.getNumber());name.setText(l.getName());}});u.setOnAction(e->{try{Level l=s.read(id.getText());if(l==null)throw new IllegalArgumentException("No existe");l.setNumber(Integer.parseInt(num.getText()));l.setName(name.getText());s.update(id.getText(),l);refresh(list);}catch(Exception x){error(x.getMessage());}});d.setOnAction(e->{s.delete(id.getText());refresh(list);});all.setOnAction(e->refresh(list));GridPane form=new GridPane();form.setHgap(8);form.setVgap(8);form.addRow(0,new Label("ID:"),id);form.addRow(1,new Label("Número:"),num);form.addRow(2,new Label("Nombre:"),name);VBox root=new VBox(10,form,new HBox(8,c,r,u,d,all),list);root.setPadding(new Insets(15));w.setScene(new Scene(root,650,500));w.showAndWait();}void refresh(ListView<String> l){l.getItems().clear();s.readAll().forEach(x->l.getItems().add("#"+x.getNumber()+" | "+x.getId()+" | "+x.getName()));}void error(String m){new Alert(Alert.AlertType.ERROR,m==null?"Error":m).showAndWait();}}